import { useState } from "react";
import { Pagination, PaginationControls } from "@/registry/erbium/ui/pagination";

const pageCount = 10;

export default function PaginationExample() {
  const [page, setPage] = useState(5);

  return (
    <div className="flex flex-col gap-group">
      <Pagination>
        <PaginationControls page={page} pageCount={pageCount} onPageChange={setPage} />
      </Pagination>
      <p className="text-center text-caption text-muted-foreground" aria-live="polite">
        Page {page} of {pageCount}
      </p>
    </div>
  );
}

import { createContext, use, useMemo, useState } from "react";
import {
  createMemoryHistory,
  createRootRouteWithContext,
  createRoute,
  createRouter,
  RouterProvider,
  useLocation,
} from "@tanstack/react-router";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Pagination, PaginationControls } from "@/registry/erbium/ui/pagination";
import { Switch } from "@/registry/erbium/ui/switch";

// Each page waits this long for its data, as a slow API would.
const loadTime = 900;
const pageSize = 4;
const rowCount = 42;
const pageCount = Math.ceil(rowCount / pageSize);

const wait = async (ms: number) => {
  // Browsers have no promise-based timer, so the delay wraps `setTimeout`.
  // oxlint-disable-next-line promise/avoid-new
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

const toPage = (value: number) => (Number.isInteger(value) && value >= 1 ? value : 1);

const rowsOf = (page: number) =>
  Array.from({ length: pageSize }, (_, index) => (page - 1) * pageSize + index + 1)
    .filter((row) => row <= rowCount)
    .map((row) => `INV${String(row).padStart(3, "0")}`);

// When the latest click happened and when each page finished loading, so a page can
// report how long the user waited for it.
interface Timing {
  clickedAt: () => number;
  markClick: () => void;
  readyAt: Map<number, number>;
}

const createTiming = (): Timing => {
  let clickedAt = 0;

  return {
    clickedAt: () => clickedAt,
    markClick: () => {
      clickedAt = performance.now();
    },
    readyAt: new Map(),
  };
};

const TimingContext = createContext<Timing>(createTiming());

const statusOf = (page: number, { clickedAt, readyAt }: Timing) => {
  if (clickedAt() === 0) {
    return `Each page takes ${loadTime} ms to load.`;
  }

  const waited = Math.round((readyAt.get(page) ?? 0) - clickedAt());

  return waited > 0
    ? `Page ${page} loaded ${waited} ms after the click.`
    : `Page ${page} was ready ${-waited} ms before the click.`;
};

const PredictContext = createContext(true);

const useCurrentPage = () =>
  useLocation({
    select: (location) => toPage(Number(new URLSearchParams(location.searchStr).get("page") ?? 1)),
  });

const Controls = () => {
  const page = useCurrentPage();
  const predict = use(PredictContext);
  const { markClick } = use(TimingContext);

  return (
    <Pagination onClickCapture={markClick}>
      <PaginationControls
        page={page}
        pageCount={pageCount}
        linkOptions={(target) => ({
          preload: predict ? undefined : false,
          search: { page: target },
          to: "/",
        })}
      />
    </Pagination>
  );
};

const Invoices = () => {
  const page = useCurrentPage();
  const timing = use(TimingContext);

  return (
    <div className="flex flex-col gap-group">
      <ul className="flex flex-col gap-related rounded-lg border border-border p-4 tabular-nums">
        {rowsOf(page).map((invoice) => (
          <li key={invoice}>{invoice}</li>
        ))}
      </ul>
      <Controls />
      <p className="text-center text-caption text-muted-foreground" aria-live="polite">
        {statusOf(page, timing)}
      </p>
    </div>
  );
};

const InvoicesPending = () => (
  <div className="flex flex-col gap-group">
    <p className="rounded-lg border border-border p-4 text-muted-foreground">Loading…</p>
    <Controls />
  </div>
);

const rootRoute = createRootRouteWithContext<Pick<Timing, "readyAt">>()({});

const invoicesRoute = createRoute({
  component: Invoices,
  getParentRoute: () => rootRoute,
  // The page is a search param, so each page is its own loader entry and cache key.
  loader: async ({ context, deps }) => {
    await wait(loadTime);
    context.readyAt.set(deps.page, performance.now());
  },
  loaderDeps: ({ search }: { search: { page: number } }) => ({ page: search.page }),
  path: "/",
  pendingComponent: InvoicesPending,
  validateSearch: ({ page }: { page?: number }) => ({ page: toPage(page ?? 1) }),
});

const routeTree = rootRoute.addChildren([invoicesRoute]);

export default function PaginationRouterExample() {
  const [predict, setPredict] = useState(true);
  const timing = useMemo(() => createTiming(), []);

  const router = useMemo(
    () =>
      createRouter({
        context: { readyAt: timing.readyAt },
        defaultPendingMs: 0,
        defaultPreload: "intent",
        history: createMemoryHistory({ initialEntries: ["/?page=1"] }),
        routeTree,
      }),
    [timing],
  );

  return (
    <div className="flex w-full max-w-md flex-col gap-group">
      <TimingContext value={timing}>
        <PredictContext value={predict}>
          <RouterProvider router={router} />
        </PredictContext>
      </TimingContext>
      <Field orientation="horizontal" className="justify-center">
        <Switch checked={predict} onCheckedChange={setPredict} />
        <FieldLabel>Preload pages</FieldLabel>
      </Field>
    </div>
  );
}

import { useRef, useState } from "react";
import {
  createColumnHelper,
  rowPaginationFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Pagination, PaginationControls } from "@/registry/erbium/ui/pagination";
import { Switch } from "@/registry/erbium/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";

// The server takes this long to answer each page request.
const loadTime = 700;
const pageSize = 4;
const rowCount = 42;

interface Invoice {
  invoice: string;
  amount: number;
}

const wait = async (ms: number) => {
  // Browsers have no promise-based timer, so the delay wraps `setTimeout`.
  // oxlint-disable-next-line promise/avoid-new
  await new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
};

const rowsOf = (page: number): Invoice[] =>
  Array.from({ length: pageSize }, (_, index) => (page - 1) * pageSize + index + 1)
    .filter((row) => row <= rowCount)
    .map((row) => ({
      amount: ((row * 37) % 900) + 100,
      invoice: `INV${String(row).padStart(3, "0")}`,
    }));

// Stands in for an API that returns one page of rows.
const fetchInvoices = async (page: number) => {
  await wait(loadTime);

  return rowsOf(page);
};

const currency = new Intl.NumberFormat("en-US", { currency: "USD", style: "currency" });

const features = tableFeatures({ rowPaginationFeature });

const columnHelper = createColumnHelper<typeof features, Invoice>();

const columns = columnHelper.columns([
  columnHelper.accessor("invoice", { header: "Invoice" }),
  columnHelper.accessor("amount", {
    cell: (info) => currency.format(info.getValue()),
    header: "Amount",
  }),
]);

interface Loaded {
  page: number;
  rows: Invoice[];
  // Milliseconds from the click to the rows, or -1 for the first page.
  waited: number;
}

const statusOf = (page: number, loaded: Loaded) => {
  if (loaded.page !== page) {
    return `Loading page ${page}…`;
  }

  if (loaded.waited < 0) {
    return `Each page takes ${loadTime} ms to load.`;
  }

  if (loaded.waited > 50) {
    return `Page ${page} loaded ${loaded.waited} ms after the click.`;
  }

  return `Page ${page} was fetched before the click.`;
};

export default function PaginationTableExample() {
  const [predict, setPredict] = useState(true);
  const [page, setPage] = useState(1);
  // The first page arrives with the document, as a route loader would provide it.
  const [loaded, setLoaded] = useState<Loaded>({ page: 1, rows: rowsOf(1), waited: -1 });
  const latestPage = useRef(1);

  // A cache of page requests, as TanStack Query or an atom family would keep. A request
  // started by `onPageIntent` is reused by the click.
  const requests = useRef(new Map<number, Promise<Invoice[]>>());

  const request = async (target: number) => {
    const cached = requests.current.get(target);

    if (cached !== undefined) {
      return await cached;
    }

    const pending = fetchInvoices(target);
    requests.current.set(target, pending);

    return await pending;
  };

  const goTo = async (target: number) => {
    const clickedAt = performance.now();
    latestPage.current = target;
    setPage(target);
    const rows = await request(target);

    // A later click wins over a slower earlier one.
    if (latestPage.current === target) {
      setLoaded({ page: target, rows, waited: Math.round(performance.now() - clickedAt) });
    }
  };

  const table = useTable({
    columns,
    data: loaded.rows,
    features,
    manualPagination: true,
    rowCount,
    state: { pagination: { pageIndex: page - 1, pageSize } },
  });

  const isLoading = loaded.page !== page;

  return (
    <div className="flex w-full max-w-md flex-col gap-group">
      <Table aria-busy={isLoading} className={isLoading ? "opacity-50" : undefined}>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id}>
                  <table.FlexRender header={header} />
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows.map((row) => (
            <TableRow key={row.id}>
              {row.getAllCells().map((cell) => (
                <TableCell key={cell.id} className="tabular-nums">
                  <table.FlexRender cell={cell} />
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
      <Pagination>
        <PaginationControls
          page={page}
          pageCount={table.getPageCount()}
          onPageChange={(target) => {
            void goTo(target);
          }}
          onPageIntent={
            predict
              ? (target) => {
                  void request(target);
                }
              : undefined
          }
        />
      </Pagination>
      <p className="text-center text-caption text-muted-foreground" aria-live="polite">
        {statusOf(page, loaded)}
      </p>
      <Field orientation="horizontal" className="justify-center">
        <Switch checked={predict} onCheckedChange={setPredict} />
        <FieldLabel>Prefetch on intent</FieldLabel>
      </Field>
    </div>
  );
}

