  parameters: {
    docs: {
      description: { story: "Pages kept in the URL. `linkOptions` returns Router's link options for each page, and every control renders a link that starts loading its page when the pointer heads for it. Each page takes 900 ms to load. Move toward a page number and click it, then turn preloading off and compare." },
      source: { code: "import { createContext, use, useMemo, useState } from "react";
import {
  createMemoryHistory,
  createRootRouteWithContext,
